{
  "schema_version": 1,
  "run_id": "20261012-004104-3d33dd",
  "kept": [
    {
      "finding_id": "F-GAP-001-01",
      "notes": "The claim restates the source sentence at sources/SRC-2c9eb1bc.txt line 3 ('Show each validation message next to the field it relates to, and keep everything the user entered when validation fails.') without strengthening it. It bears on GAP-001 research question 1 (validation and error messaging for a mandatory reject reason). The recommendation is conditional ('If the rejection reason is captured in a dialog or inline step'), applies only the two stated practices to the reason field that DEC-002 makes mandatory, adds no numbers or scope, and is labelled as an inference.",
      "limitations": [
        "The source states 'This page is a test fixture for the Feature Research Agent and is not real documentation' (line 6); although its metadata says source_type official_documentation, the spec must not present it as authoritative published guidance.",
        "General form-validation guidance published 2025-03-01; it says nothing specific to reject-reason capture, dialog versus inline placement, or minimum length.",
        "Applying it to the rejection reason field is an inference for this product, not a customer-confirmed requirement."
      ]
    },
    {
      "finding_id": "F-GAP-001-02",
      "notes": "The claim matches sources/SRC-2c9eb1bc.txt line 4 ('Do not rely on colour alone to show that a field has an error; include text that names the problem.'). It bears on error messaging for the required reason field (GAP-001 research question 1) and on error identification (research question 2). It makes no recommendation and adds nothing beyond the source.",
      "limitations": [
        "The source says it is a test fixture and not real documentation (line 6), so the spec must not present it as authoritative.",
        "It does not cite any WCAG 2.2 success criterion, so it does not answer which success criteria apply; that question stays unanswered."
      ]
    },
    {
      "finding_id": "F-GAP-001-03",
      "notes": "The claim matches sources/SRC-2c9eb1bc.txt line 5 word for word, including the stated reason ('because client-side checks can be bypassed'). The recommendation to enforce the mandatory reason on the server as well as in the UI follows directly from that sentence combined with DEC-002 ('A reason is required when rejecting a claim.'). It adds no new numbers or scope and is labelled as an inference.",
      "limitations": [
        "The source says it is a test fixture and not real documentation (line 6), so the spec must not present it as authoritative.",
        "General guidance on required fields; it does not mention reject actions or approval workflows specifically."
      ]
    },
